import React, { useState } from 'react';
import CreatorView from './pages/CreatorView';
import ConsumerView from './pages/ConsumerView';
import './App.css';

function App() {
  const [currentView, setCurrentView] = useState('consumer'); // 'creator' or 'consumer'

  return (
    <div className="app">
      <header className="app-header">
        <h1>Social Media Platform</h1>
        <nav>
          <button onClick={() => setCurrentView('consumer')}>Consumer View</button>
          <button onClick={() => setCurrentView('creator')}>Creator View</button>
        </nav>
      </header>
      <main>
        {currentView === 'creator' ? <CreatorView /> : <ConsumerView />}
      </main>
    </div>
  );
}

export default App;
